:root {
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-color: #f8fafc;
    --text-muted: #94a3b8;
    --accent: #3b82f6;
    --border: #334155;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-color);
    margin: 0;
    padding: 16px;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.header {
    width: 100%;
    max-width: 600px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 24px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--border);
}

.logo-area {
    display: flex;
    align-items: center;
    gap: 12px;
}

.logo-area img {
    height: 24px;
}

.logo-area h1 {
    font-size: 1.1rem;
    margin: 0;
}

.login-btn {
    color: var(--accent);
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 500;
}

.main-container {
    width: 100%;
    max-width: 600px;
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.card {
    background-color: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
}

.card h2 {
    font-size: 1.1rem;
    margin-top: 0;
    margin-bottom: 12px;
    color: var(--text-color);
}

.card p {
    font-size: 0.9rem;
    color: var(--text-muted);
    line-height: 1.4;
    margin-bottom: 16px;
}

.setting-item {
    margin-top: 12px;
}

.setting-item h3 {
    font-size: 0.95rem;
    margin-bottom: 8px;
}

.badge {
    display: inline-block;
    background-color: rgba(59, 130, 246, 0.15);
    color: var(--accent);
    padding: 4px 10px;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 500;
}

.options-group {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    margin-top: 8px;
}

.opt-btn {
    background: transparent;
    border: 1px solid var(--border);
    color: var(--text-color);
    padding: 8px 14px;
    border-radius: 8px;
    font-size: 0.85rem;
    cursor: pointer;
}

.opt-btn.active {
    background-color: var(--accent);
    border-color: var(--accent);
}

.checkbox-item {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 14px;
    font-size: 0.9rem;
}

.action-bar {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    margin-top: 8px;
}

.btn {
    padding: 10px 20px;
    border-radius: 8px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
}

.btn.primary {
    background-color: var(--accent);
    color: white;
}

.btn.secondary {
    background: transparent;
    color: var(--text-muted);
    border: 1px solid var(--border);
}

.footer {
    width: 100%;
    max-width: 600px;
    display: flex;
    justify-content: center;
    gap: 20px;
    margin-top: 32px;
    padding-top: 16px;
    border-top: 1px solid var(--border);
}

.footer a {
    color: var(--text-muted);
    text-decoration: none;
    font-size: 0.85rem;
}

document.addEventListener('DOMContentLoaded', () => {
    console.log("Interface des paramètres initialisée.");

    const optButtons = document.querySelectorAll('.opt-btn');
    optButtons.forEach(btn => {
        btn.addEventListener('click', (e) => {
            const parent = e.target.parentElement;
            parent.querySelectorAll('.opt-btn').forEach(b => b.classList.remove('active'));
            e.target.classList.add('active');
        });
    });

    const confirmBtn = document.querySelector('.btn.primary');
    if (confirmBtn) {
        confirmBtn.addEventListener('click', () => {
            alert('Préférences enregistrées avec succès.');
        });
    }
});
